    """R1: The recorder role is registered in the institution"""
    with open('state/institution.json', 'r') as f:
        institution = json.load(f)

    assert 'recorder' in institution['roles']
    assert institution['roles']['recorder']['description'] == "responsible for checking the communal scale weekly and auditing the ledger"

def test_R2_weigh_catch_action_registered():
    """R2: The weigh_catch action is registered and accessible"""
    with open('state/institution.json', 'r') as f:
        institution = json.load(f)

    assert 'weigh_catch' in institution['actions']
    assert institution['actions']['weigh_catch']['protected'] == False

